//! Generates the Rust types and gRPC stubs of the three protos into src/protogen. The
//! generated files are kept in the repo: a Windows build uses them as they are, with no
//! protoc. diff_doc.proto, which base.proto imports, is diff-doc-rs's: proto/ holds the
//! copy ytpgc/Makefile keeps of it, for protoc, and its Rust types are the diff_doc
//! crate's (feature `proto`).
use std::fs;
use std::path::PathBuf;

const PROTO_DIR: &str = "proto";
const GEN_DIR: &str = "src/protogen";
const PROTOS: [&str; 3] = ["base", "db", "link"];
const BANNER: &str = "\nDO NOT MODIFY!!!\ngenerated by build.rs ";

/// The extension's version is the repo's VERSION file: its major.minor names the SQL
/// script (config.rs EXT_SQL).
fn ext_version() -> Result<(), Box<dyn std::error::Error>> {
	let path = "../VERSION";
	println!("cargo::rerun-if-changed={path}");
	let v = fs::read_to_string(path).map_err(|e| format!("{path}: {e}"))?;
	// three numbers and nothing else: the extension's version is the first two, and a
	// suffix (1.21.0-rc1) would be dropped without a word
	let parts: Vec<&str> = v.trim().split('.').collect();
	if parts.len() != 3 || parts.iter().any(|p| p.is_empty() || !p.bytes().all(|b| b.is_ascii_digit())) {
		return Err(format!("{path}: '{}' is no <major>.<minor>.<patch> version", v.trim()).into());
	}
	let (major, minor) = (parts[0], parts[1]);
	println!("cargo::rustc-env=YT_EXT_MAJOR_MINOR={major}.{minor}");
	Ok(())
}

#[cfg(windows)]
fn main() -> Result<(), Box<dyn std::error::Error>> {
	println!("cargo::rerun-if-changed=build.rs");
	ext_version()
}

#[cfg(not(windows))]
fn main() -> Result<(), Box<dyn std::error::Error>> {
	println!("cargo::rerun-if-changed=build.rs");
	ext_version()?;
	for p in PROTOS {
		println!("cargo::rerun-if-changed={PROTO_DIR}/{p}.proto");
	}
	println!("cargo::rerun-if-changed={PROTO_DIR}/diff_doc.proto");
	let tmp = PathBuf::from(std::env::var("OUT_DIR")?).join("protogen");
	fs::create_dir_all(&tmp)?;
	fs::create_dir_all(GEN_DIR)?;
	let files: Vec<String> = PROTOS.iter().map(|p| format!("{p}.proto")).collect();
	tonic_prost_build::configure()
		.type_attribute(".", "#[derive(serde::Serialize, serde::Deserialize)]")
		.server_mod_attribute(".", "#[cfg(feature = \"server\")]")
		.extern_path(".diff_doc", "::diff_doc::proto")
		.out_dir(&tmp)
		.compile_protos(&files, &[PROTO_DIR.to_string()])?;
	let mut mods = format!("/* {BANNER} */\n");
	for name in PROTOS {
		let from = tmp.join(format!("{name}.rs"));
		let dest = format!("{GEN_DIR}/{name}.rs");
		let mut contents = fs::read_to_string(&from).map_err(|e| format!("{}: {e}", from.display()))?;
		contents.insert_str(0, &format!("/* {BANNER} into '{dest}' \n*/\n"));
		// a client connects with a timeout: `connect(timeout, endpoint)`
		patch(&mut contents, "connect<D>(", "d: core::time::Duration, ", false);
		patch(&mut contents, ".connect()", ".connect_timeout(d)", true);
		// [i18n] tonic's "Service was not ready" in the binary's language, under its code
		// (src/i18n.rs)
		let contents = contents.replace("format!(\"Service was not ready: {}\", e.into())", "crate::i18n::not_ready(e.into())");
		if fs::read_to_string(&dest).ok().as_deref() != Some(contents.as_str()) {
			fs::write(&dest, contents)?;
		}
		mods.push_str(&format!("pub mod {name};\n"));
	}
	let mod_rs = format!("{GEN_DIR}/mod.rs");
	if fs::read_to_string(&mod_rs).ok().as_deref() != Some(mods.as_str()) {
		fs::write(&mod_rs, mods)?;
	}
	Ok(())
}

/// Insert `add` at the first `pattern`: after it, or before it with `before`.
#[cfg(not(windows))]
fn patch(cnt: &mut String, pattern: &str, add: &str, before: bool) {
	if let Some(i) = cnt.find(pattern) {
		cnt.insert_str(i + if before { 0 } else { pattern.len() }, add);
	}
}
